const pptxgen = require("pptxgenjs");
const { applyTheme } = require(process.env.SKILL + "/scripts/apply_theme.js");

// Thermal palette: cold steel blue (strips) -> hot orange (blocks), dark ink, white page.
const THEME = {
  name: "Heat MPI",
  headFontFace: "Cambria",
  bodyFontFace: "Calibri",
  colors: {
    dk1: "1E2A36", lt1: "FFFFFF", dk2: "5B6B7A", lt2: "F2F4F6",
    accent1: "E4572E", accent2: "2E7DA6", accent3: "F3A712", accent4: "9CC3D9",
    accent5: "F2B5A0", accent6: "8A97A3", hlink: "2E7DA6", folHlink: "5B6B7A",
  },
};
const HEX = THEME.colors;
const OUT = process.argv[2] || "heat-mpi-slides.pptx";

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE"; // 13.333 x 7.5 in
pres.theme = { headFontFace: THEME.headFontFace, bodyFontFace: THEME.bodyFontFace };
pres.title = "Heat MPI Project";
pres.author = "Mahmoud Hachem, Ali Harkous, Amer Soulak";
const C = pres.SchemeColor;

pres.defineSlideMaster({
  title: "CONTENT",
  background: { color: HEX.lt1 },
  objects: [
    { placeholder: { options: { name: "kicker", type: "body", x: 0.55, y: 0.32, w: 9, h: 0.32, fontSize: 12,
        bold: true, color: C.accent1, charSpacing: 2, margin: 0, valign: "middle" }, text: "" } },
    { placeholder: { options: { name: "title", type: "title", x: 0.55, y: 0.62, w: 12.2, h: 0.75, fontSize: 32,
        bold: true, color: C.text1, fontFace: THEME.headFontFace, margin: 0, valign: "top" }, text: "" } },
    { text: { text: "Parallel 2D heat diffusion with MPI over Tailscale  ·  Hachem · Harkous · Soulak",
        options: { x: 0.55, y: 7.05, w: 9, h: 0.3, fontSize: 10, color: C.text2, margin: 0 } } },
  ],
  slideNumber: { x: 12.35, y: 7.05, w: 0.45, h: 0.3, fontSize: 10, color: C.text2, align: "right" },
});

// Motif: the five-point stencil (centre + four neighbours) drawn as five small squares.
function stencil(slide, x, y, s = 0.11, hot = C.accent1, cold = C.accent2) {
  const g = s * 0.18;
  const cells = [[1, 0], [0, 1], [2, 1], [1, 2]];
  cells.forEach(([i, j]) => slide.addShape(pres.shapes.RECTANGLE, {
    x: x + i * (s + g), y: y + j * (s + g), w: s, h: s, fill: { color: cold }, line: { type: "none" },
    objectName: "stencil" }));
  slide.addShape(pres.shapes.RECTANGLE, { x: x + (s + g), y: y + (s + g), w: s, h: s,
    fill: { color: hot }, line: { type: "none" }, objectName: "stencil centre" });
}

function header(slide, text, x, y, w) {
  stencil(slide, x, y + 0.04);
  slide.addText(text, { x: x + 0.5, y, w: w - 0.5, h: 0.38, fontSize: 16, bold: true, color: C.text1,
    margin: 0, valign: "middle", isTextBox: true, objectName: "section header" });
}

function card(slide, x, y, w, h, name) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x, y, w, h, rectRadius: 0.08,
    fill: { color: C.background2 }, line: { type: "none" }, objectName: name || "card" });
}

const MUTED = { color: C.text2 };

// ------------------------------------------------------------------ Slide 1
{
  const s = pres.addSlide({ masterName: "CONTENT" });
  s.addText("01  ·  INFRASTRUCTURE", { placeholder: "kicker" });
  s.addText("Three laptops, one VM each, joined by Tailscale", { placeholder: "title" });

  // Hardware rows
  header(s, "Hardware per VM", 0.55, 1.6, 6.3);
  const vms = [
    ["heat-1", "AMD Ryzen 7 6800H", "21.3", "1.6"],
    ["heat-2", "Intel Core i7-10510U, 1.8 GHz", "10.7", "3.0"],
    ["heat-3", "Intel Core i7-14700HX", "22.9", "1.1"],
  ];
  vms.forEach(([n, cpu, bw, tc], k) => {
    const y = 2.1 + k * 0.82;
    card(s, 0.55, y, 6.3, 0.7, `${n} card`);
    s.addText(n, { x: 0.75, y, w: 1.05, h: 0.7, fontSize: 18, bold: true, color: C.text1, margin: 0,
      valign: "middle", isTextBox: true });
    s.addText([
      { text: cpu, options: { bold: true, breakLine: true } },
      { text: "2 vCPU · 3.8 GiB · no GPU", options: MUTED },
    ], { x: 1.8, y, w: 2.9, h: 0.7, fontSize: 13, color: C.text1, margin: 0, valign: "middle", isTextBox: true });
    s.addText([
      { text: bw, options: { fontSize: 20, bold: true, color: C.accent1 } },
      { text: " GB/s", options: { fontSize: 12, color: C.text2, breakLine: true } },
      { text: "memory (triad)", options: { fontSize: 11, color: C.text2 } },
    ], { x: 4.7, y, w: 1.25, h: 0.7, margin: 0, valign: "middle", align: "right", isTextBox: true });
    s.addText([
      { text: tc, options: { fontSize: 20, bold: true, color: C.text1 } },
      { text: " ns", options: { fontSize: 12, color: C.text2, breakLine: true } },
      { text: "tᴄ / update", options: { fontSize: 11, color: C.text2 } },
    ], { x: 5.95, y, w: 0.8, h: 0.7, margin: 0, valign: "middle", align: "right", isTextBox: true });
  });
  s.addText("Ubuntu 24.04 · VirtualBox · Open MPI 4.1.6 · MPI pinned to tailscale0, btl tcp,self",
    { x: 0.55, y: 4.55, w: 6.3, h: 0.3, fontSize: 12, color: C.text2, margin: 0, isTextBox: true });

  // Network table
  header(s, "Network: MPI ping-pong, t = tₛ + m·tᵂ", 7.25, 1.6, 5.55);
  const hd = { bold: true, color: C.text1, fill: { color: C.background2 } };
  const rows = [
    [{ text: "Link", options: hd }, { text: "Latency", options: { ...hd, align: "right" } },
     { text: "Bandwidth", options: { ...hd, align: "right" } }],
    ["Same VM (shared memory via TCP)", { text: "7–17 µs", options: { align: "right" } },
     { text: "3.2–4.1 GB/s", options: { align: "right" } }],
    ["heat-2 ↔ heat-3, hotspot", { text: "6.83 ms", options: { align: "right", bold: true } },
     { text: "5.81 MB/s", options: { align: "right", bold: true } }],
    ["heat-2 ↔ heat-1, Wi-Fi", { text: "3.51 ms", options: { align: "right" } },
     { text: "1.75 MB/s", options: { align: "right" } }],
    ["heat-1 ↔ heat-3, Wi-Fi", { text: "4.14 ms", options: { align: "right" } },
     { text: "1.47 MB/s", options: { align: "right" } }],
  ];
  s.addTable(rows, { x: 7.25, y: 2.1, w: 5.55, colW: [2.85, 1.2, 1.5], rowH: 0.42, fontSize: 13,
    color: C.text1, fontFace: THEME.bodyFontFace, border: { type: "solid", pt: 0.75, color: "D9DEE3" },
    valign: "middle", margin: [0, 0.08, 0, 0.08], objectName: "network table" });
  s.addText([
    { text: "Memory is ", options: {} },
    { text: "~2,000–15,000×", options: { bold: true, color: C.accent1 } },
    { text: " faster than a cross-VM link: every halo exchange that leaves a VM dominates the step.", options: {} },
  ], { x: 7.25, y: 4.35, w: 5.55, h: 0.55, fontSize: 13, color: C.text1, margin: 0, valign: "top",
    isTextBox: true });

  // Best time per step
  header(s, "Best measured time per step", 0.55, 5.05, 6.3);
  const best = [["0.45 ms", "N = 512", "strips, P = 2, one VM"], ["6.8 ms", "N = 2048", "strips, P = 2, one VM"],
    ["111 ms", "N = 8192", "blocks, P = 4, heat-2 + heat-3"]];
  best.forEach(([v, n, how], k) => {
    const x = 0.55 + k * 2.15;
    card(s, x, 5.5, 2.0, 1.35, `best ${n}`);
    s.addText([
      { text: n, options: { fontSize: 12, color: C.text2, breakLine: true } },
      { text: v, options: { fontSize: 24, bold: true, color: k === 2 ? C.accent1 : C.text1, breakLine: true } },
      { text: how, options: { fontSize: 11, color: C.text2 } },
    ], { x: x + 0.15, y: 5.55, w: 1.75, h: 1.25, margin: 0, valign: "middle", isTextBox: true });
  });

  // Computation vs communication prediction (native stacked bar)
  header(s, "Model: computation vs communication per step", 7.25, 5.05, 5.55);
  s.addChart(pres.charts.BAR, [
    { name: "Computation", labels: ["N = 512", "N = 2048", "N = 8192"], values: [0.14, 2.9, 50.6] },
    { name: "Communication", labels: ["N = 512", "N = 2048", "N = 8192"], values: [14.4, 16.5, 25.0] },
  ], { x: 7.15, y: 5.4, w: 4.0, h: 1.55, barDir: "bar", barGrouping: "stacked", chartColors: [HEX.accent3, HEX.accent2],
    catAxisLabelColor: HEX.dk2, valAxisLabelColor: HEX.dk2, catAxisLabelFontSize: 11, valAxisLabelFontSize: 10,
    catAxisLabelFontFace: "+mn-lt", valAxisLabelFontFace: "+mn-lt", valGridLine: { color: "E3E7EB", size: 0.5 },
    catGridLine: { style: "none" }, valAxisTitle: "ms per step", showValAxisTitle: true, valAxisTitleFontSize: 10,
    valAxisTitleColor: HEX.dk2, valAxisTitleFontFace: "+mn-lt", catAxisOrientation: "maxMin",
    showLegend: true, legendPos: "t", legendFontSize: 10, legendFontFace: "+mn-lt", legendColor: HEX.dk2,
    objectName: "comp vs comm chart" });
  s.addText([
    { text: "Blocks, P = 4 on heat-2 + heat-3", options: { bold: true, breakLine: true } },
    { text: "Predicted comm share 99 %, 85 %, 33 %. Measured at N = 8192: 72–83 %.", options: MUTED },
  ], { x: 11.2, y: 5.5, w: 1.6, h: 1.35, fontSize: 11, color: C.text1, margin: 0, valign: "middle",
    isTextBox: true });

  s.addNotes("Hardware from lscpu/free/lspci and a STREAM-style triad (part0/results/hardware). Network from the " +
    "MPI ping-pong fit (part0/results). Best time per step = best median of 10 steps / 10. Model: refined " +
    "placement-aware prediction (part4/results/consolidated/model_vs_measured.csv).");
}

// ------------------------------------------------------------------ Slide 2
{
  const s = pres.addSlide({ masterName: "CONTENT" });
  s.addText("02  ·  METHOD", { placeholder: "kicker" });
  s.addText("Explicit stencil, two decompositions, one cost model", { placeholder: "title" });

  const cw = 4.15, ch = 2.45, gx = 0.3, x0 = 0.55, y0 = 1.65;
  const pos = [[x0, y0], [x0 + cw + gx, y0], [x0, y0 + ch + gx], [x0 + cw + gx, y0 + ch + gx]];
  pos.forEach(([x, y], k) => card(s, x, y, cw, ch, `method card ${k + 1}`));
  const sub = (t) => ({ text: t, options: { subscript: true } });
  const sup = (t) => ({ text: t, options: { superscript: true } });

  // Discretization
  {
    const [x, y] = pos[0];
    header(s, "Discretization", x + 0.25, y + 0.2, cw - 0.5);
    s.addText([
      { text: "u" }, sub("i,j"), sup("n+1"), { text: " = u" }, sub("i,j"), sup("n"),
      { text: " + r (u" }, sub("i±1,j"), sup("n"), { text: " + u" }, sub("i,j±1"), sup("n"),
      { text: " − 4u" }, sub("i,j"), sup("n"), { text: ")" },
    ], { x: x + 0.25, y: y + 0.7, w: cw - 0.5, h: 0.5, fontSize: 15, color: C.text1, margin: 0,
      valign: "middle", isTextBox: true, objectName: "stencil equation" });
    s.addText([
      { text: "FTCS on the unit square, h = 1/N, α = 1", options: { bullet: true, breakLine: true } },
      { text: "Stable for r = Δt/h² ≤ 1/4 (r = 0.2625 diverges)", options: { bullet: true, breakLine: true } },
      { text: "Cases 1, 2 and V (exact: sinπx sinπy e^−2π²t)", options: { bullet: true } },
    ], { x: x + 0.25, y: y + 1.25, w: cw - 0.4, h: 1.05, fontSize: 13, color: C.text1, margin: 0,
      paraSpaceAfter: 3, valign: "top", isTextBox: true });
  }
  // Compute model
  {
    const [x, y] = pos[1];
    header(s, "Compute model", x + 0.25, y + 0.2, cw - 0.5);
    s.addText([
      { text: "T" }, sub("comp"), { text: " = n" }, sub("owned"), { text: " · t" }, sub("c"),
      { text: "(VM)" },
    ], { x: x + 0.25, y: y + 0.7, w: cw - 0.5, h: 0.5, fontSize: 15, color: C.text1, margin: 0,
      valign: "middle", isTextBox: true });
    s.addText([
      { text: "tᴄ from the serial baseline: 1.1, 1.6, 3.0 ns", options: { bullet: true, breakLine: true } },
      { text: "Memory-bound: ~24 B per update ÷ triad bandwidth predicts the same ranking", options: { bullet: true, breakLine: true } },
      { text: "heat-2 is slowest and sets the pace", options: { bullet: true } },
    ], { x: x + 0.25, y: y + 1.25, w: cw - 0.4, h: 1.05, fontSize: 13, color: C.text1, margin: 0,
      paraSpaceAfter: 3, valign: "top", isTextBox: true });
  }
  // Decomposition with diagrams
  {
    const [x, y] = pos[2];
    header(s, "Decomposition", x + 0.25, y + 0.2, cw - 0.5);
    const sq = 1.05, dy = y + 0.72;
    // strips
    const sx = x + 0.35;
    const stripCols = [HEX.accent4, HEX.accent2, HEX.accent4, HEX.accent2];
    stripCols.forEach((c, k) => s.addShape(pres.shapes.RECTANGLE, { x: sx, y: dy + k * sq / 4, w: sq, h: sq / 4,
      fill: { color: c }, line: { color: "FFFFFF", width: 1.5 }, objectName: "strip" }));
    // blocks
    const bx = x + 2.25;
    [[0, 0, HEX.accent5], [1, 0, HEX.accent1], [0, 1, HEX.accent1], [1, 1, HEX.accent5]].forEach(([i, j, c]) =>
      s.addShape(pres.shapes.RECTANGLE, { x: bx + i * sq / 2, y: dy + j * sq / 2, w: sq / 2, h: sq / 2,
        fill: { color: c }, line: { color: "FFFFFF", width: 1.5 }, objectName: "block" }));
    s.addText([
      { text: "Strips", options: { bold: true, breakLine: true } },
      { text: "2 Sendrecv × (N+1)", options: MUTED },
    ], { x: sx - 0.05, y: dy + sq + 0.08, w: 1.8, h: 0.5, fontSize: 12, color: C.text1, margin: 0, isTextBox: true });
    s.addText([
      { text: "Blocks (Cartesian)", options: { bold: true, breakLine: true } },
      { text: "4 Sendrecv × N/√P", options: MUTED },
    ], { x: bx - 0.05, y: dy + sq + 0.08, w: 1.8, h: 0.5, fontSize: 12, color: C.text1, margin: 0, isTextBox: true });
    s.addText("Columns via MPI_Type_vector · corners never exchanged (5-point stencil)",
      { x: x + 0.25, y: y + 2.1, w: cw - 0.4, h: 0.3, fontSize: 11, color: C.text2, margin: 0, isTextBox: true });
  }
  // Performance model
  {
    const [x, y] = pos[3];
    header(s, "Performance model", x + 0.25, y + 0.2, cw - 0.5);
    s.addText([
      { text: "T" }, sub("step"), { text: " = max" }, sub("rank"), { text: " [ n" }, sub("own"), { text: "t" },
      sub("c"), { text: " + Σ (t" }, sub("s"), { text: " + m·t" }, sub("w"), { text: ") ]" },
    ], { x: x + 0.25, y: y + 0.7, w: cw - 0.5, h: 0.5, fontSize: 15, color: C.text1, margin: 0,
      valign: "middle", isTextBox: true });
    s.addText([
      { text: "Real neighbours, real link: same VM or cross-VM", options: { bullet: true, breakLine: true } },
      { text: "Placement-aware: slot fills heat-2, then heat-1, heat-3", options: { bullet: true, breakLine: true } },
      { text: "Simple Task 8.2 form picks strips; refined form picks blocks", options: { bullet: true } },
    ], { x: x + 0.25, y: y + 1.25, w: cw - 0.4, h: 1.05, fontSize: 13, color: C.text1, margin: 0,
      paraSpaceAfter: 3, valign: "top", isTextBox: true });
  }

  // Right column: verification callouts
  const rx = 9.55, rw = 3.25;
  card(s, rx, 1.65, rw, 2.45, "convergence callout");
  s.addText([
    { text: "Convergence order", options: { fontSize: 13, color: C.text2, breakLine: true } },
    { text: "2.0001", options: { fontSize: 44, bold: true, color: C.accent1, fontFace: THEME.headFontFace, breakLine: true } },
    { text: "Case V, L₂ error, N = 16 → 256: 2.0058, 2.0014, 2.0004, 2.0001", options: { fontSize: 12, color: C.text1 } },
  ], { x: rx + 0.25, y: 1.8, w: rw - 0.5, h: 2.15, margin: 0, valign: "middle", isTextBox: true });
  card(s, rx, 4.4, rw, 2.45, "bit-identical callout");
  s.addText([
    { text: "Bit-identical to serial", options: { fontSize: 13, color: C.text2, breakLine: true } },
    { text: "108 / 108", options: { fontSize: 40, bold: true, color: C.accent2, fontFace: THEME.headFontFace, breakLine: true } },
    { text: "Strips 36/36, blocks 72/72 (Cases 1, 2, V; uneven splits; P up to 8), plus 2- and 3-VM runs", options: { fontSize: 12, color: C.text1 } },
  ], { x: rx + 0.25, y: 4.55, w: rw - 0.5, h: 2.15, margin: 0, valign: "middle", isTextBox: true });

  s.addNotes("Discretization and verification: Part 1 (Appendix D). Decompositions: Parts 2 and 3. " +
    "Model: part4/analysis/consolidate.py predict().");
}

// ------------------------------------------------------------------ Slide 3
{
  const s = pres.addSlide({ masterName: "CONTENT" });
  s.addText("03  ·  RESULTS", { placeholder: "kicker" });
  s.addText("Network-bound until N ≈ 8192, then blocks win", { placeholder: "title" });

  header(s, "Strong scaling at N = 8192: speed-up vs model", 0.55, 1.6, 7.6);
  const P = ["1", "2", "3", "4", "5", "6"];
  s.addChart(pres.charts.LINE, [
    { name: "Blocks measured", labels: P, values: [1, 1.35, 1.23, 1.19, 0.84, 1.03] },
    { name: "Blocks model", labels: P, values: [1, 2.0, 1.35, 2.13, 1.65, 2.58] },
    { name: "Strips measured", labels: P, values: [1, 1.79, 1.52, 1.34, 1.16, 1.42] },
    { name: "Strips model", labels: P, values: [1, 2.0, 1.35, 1.53, 1.65, 1.75] },
  ], { x: 0.45, y: 2.05, w: 7.8, h: 3.75, chartColors: [HEX.accent1, HEX.accent5, HEX.accent2, HEX.accent4],
    lineSize: 2.5, lineDataSymbol: "circle", lineDataSymbolSize: 7,
    catAxisTitle: "processes P (P ≤ 2 inside heat-2; P ≥ 3 across VMs, hotspot)", showCatAxisTitle: true,
    valAxisTitle: "speed-up T₁ / Tₚ", showValAxisTitle: true, valAxisMinVal: 0, valAxisMaxVal: 3,
    valAxisMajorUnit: 0.5, catAxisLabelColor: HEX.dk2, valAxisLabelColor: HEX.dk2, catAxisLabelFontSize: 11,
    valAxisLabelFontSize: 11, catAxisTitleFontSize: 11, valAxisTitleFontSize: 11, catAxisTitleColor: HEX.dk2,
    valAxisTitleColor: HEX.dk2, catAxisLabelFontFace: "+mn-lt", valAxisLabelFontFace: "+mn-lt",
    catAxisTitleFontFace: "+mn-lt", valAxisTitleFontFace: "+mn-lt", valGridLine: { color: "E3E7EB", size: 0.5 },
    catGridLine: { style: "none" }, showLegend: true, legendPos: "t", legendFontSize: 11, legendFontFace: "+mn-lt",
    legendColor: HEX.dk2, objectName: "speed-up chart" });
  s.addText([
    { text: "N ≤ 2048: ", options: { bold: true } },
    { text: "every P ≥ 3 is slower than one process (speed-up 0.02–0.29). " },
    { text: "Model accuracy: ", options: { bold: true } },
    { text: "1.2–1.9× where both link ends were measured on the hotspot; 0.96–3.2× with heat-1’s older link values." },
  ], { x: 0.55, y: 5.95, w: 7.6, h: 0.85, fontSize: 13, color: C.text1, margin: 0, valign: "top", isTextBox: true });

  // Crossover callout
  const rx = 8.65, rw = 4.15;
  card(s, rx, 1.6, rw, 2.35, "crossover callout");
  s.addText([
    { text: "Crossover grid size", options: { fontSize: 13, color: C.text2, breakLine: true } },
    { text: "N ≈ 8192", options: { fontSize: 40, bold: true, color: C.accent1, fontFace: THEME.headFontFace, breakLine: true } },
    { text: "Blocks on heat-2 + heat-3: 1.11 s vs 1.30 s for P = 2 on one VM (model 0.76 vs 1.01 s). Strips and three VMs: N = 16384 in the model.", options: { fontSize: 12, color: C.text1 } },
  ], { x: rx + 0.25, y: 1.7, w: rw - 0.5, h: 2.15, margin: 0, valign: "middle", isTextBox: true });

  // Communication share chart
  header(s, "Communication share, P = 4", rx, 4.15, rw);
  s.addChart(pres.charts.BAR, [
    { name: "Strips", labels: ["N = 512", "N = 2048", "N = 8192"], values: [98, 94, 75] },
    { name: "Blocks", labels: ["N = 512", "N = 2048", "N = 8192"], values: [98, 90, 64] },
  ], { x: rx - 0.1, y: 4.5, w: rw + 0.15, h: 2.0, barDir: "col", barGrouping: "clustered", barGapWidthPct: 60,
    chartColors: [HEX.accent2, HEX.accent1], showValue: true, dataLabelPosition: "outEnd", dataLabelFontSize: 10,
    dataLabelColor: HEX.dk1, dataLabelFontFace: "+mn-lt", dataLabelFormatCode: "0\"%\"", valAxisHidden: true,
    valAxisMinVal: 0, valAxisMaxVal: 115, valGridLine: { style: "none" }, catGridLine: { style: "none" },
    catAxisLabelColor: HEX.dk2, catAxisLabelFontSize: 11, catAxisLabelFontFace: "+mn-lt", showLegend: true,
    legendPos: "r", legendFontSize: 11, legendFontFace: "+mn-lt", legendColor: HEX.dk2, objectName: "comm share chart" });
  s.addText("Inside one VM (P = 2): 3–22 %. Cross-VM halo exchanges dominate every distributed run.",
    { x: rx, y: 6.5, w: rw, h: 0.45, fontSize: 11, color: C.text2, margin: 0, valign: "top", isTextBox: true });

  s.addNotes("Strong scaling and comm share: part4/results/consolidated (slot placement, hosts_all, medians of 3). " +
    "Crossover: model_crossover.csv and Part 3 hotspot measurements.");
}

