import json, glob, os
for f in sorted(glob.glob(os.path.expanduser(r"~/.codex/sessions/2026/11/*/rollout-*.jsonl"))):
    cwd, first, n = "?", "", 0
    hits = 0
    with open(f, encoding="utf8", errors="replace") as fh:
        for line in fh:
            n += 1
            low = line.lower()
            hits += ("heat" in low and ("mpi" in low or "report" in low))
            try:
                o = json.loads(line)
            except Exception:
                continue
            p = o.get("payload", {}) if isinstance(o.get("payload"), dict) else {}
            if o.get("type") == "session_meta":
                cwd = p.get("cwd", "?")
            if not first and o.get("type") == "response_item" and p.get("role") == "user":
                for c in p.get("content", []):
                    t = c.get("text", "")
                    if t and not t.startswith("<"):
                        first = t[:90].replace("\n", " ")
                        break
    print(f"{os.path.basename(f)[8:27]} lines={n:5d} heat={hits:4d} cwd={cwd} | {first}")

