import re, os, sys, shutil, importlib.util
from pathlib import Path
spec = importlib.util.spec_from_file_location("ex", Path(__file__).with_name("export_logs.py"))
src = Path(__file__).with_name("export_logs.py").read_text(encoding="utf8").replace("\nmain()\n", "\n")
ns = {"__file__": str(Path(__file__).with_name("export_logs.py"))}
exec(compile(src, "export_logs", "exec"), ns)

REPO = Path(r"C:\Users\User\Desktop\heat-mpi-project")
ATT = Path(os.path.expanduser("~/.codex/attachments"))
out = REPO / "llm_log/codex/attachments"
ids = set()
for f in (REPO / "llm_log/codex").glob("*.jsonl"):
    ids |= set(re.findall(r"attachments/([0-9a-f-]{36})/", f.read_text(encoding="utf8")))
for i in sorted(ids):
    d = ATT / i
    if not d.is_dir():
        print("missing", i); continue
    for f in d.rglob("*"):
        if f.is_file():
            dst = out / i / f.relative_to(d)
            dst.parent.mkdir(parents=True, exist_ok=True)
            try:
                dst.write_text(ns["scrub_str"](f.read_text(encoding="utf8")), encoding="utf8")
            except UnicodeDecodeError:
                shutil.copy2(f, dst)
            print(dst.relative_to(REPO), f.stat().st_size)
print(ns["stats"])

